    "avant": "export const PARKED_BRAKE = 1;          // pédale de frein affichée à l'arrêt (frein de parking)\n",
    "apres": "export const PARKED_BRAKE = 1;          // pédale de frein affichée à l'arrêt (frein de parking)\nexport const OVERTAKE_APPROACH_DECEL = 2.5; // décélération planifiée d'approche d'un rival (m/s²): v = sqrt(vCible² + 2·a·d), le pilote arrive déjà ralenti\n"
