const contents = new Map();
const get = (f) => {
  if (!contents.has(f)) contents.set(f, readFileSync(f, "utf8"));
  return contents.get(f);
};
const set = (f, s) => contents.set(f, s);

// Phase 1+2: vérifier chaque ancre sur le contenu ÉVOLUANT puis appliquer
// en mémoire — les diffs postérieurs s'appuient sur le texte posé par les
// précédents (S9+ modifient le contenu créé par S2/S8). AUCUNE écriture tant
// que tout n'a pas réussi: au premier échec d'ancre, STOP, fichiers intacts.
for (const d of diffs) {
  const src = get(d.file);
  const n = src.split(d.avant).length - 1;
  if (n !== 1) {
    console.error(`ANCRE ÉCHOUÉE [${d.name}] dans ${d.file}: ${n} occurrence(s), 1 attendue`);
    console.error(`--- extrait de l'ancre ---`);
    console.error(d.avant.split("\n").slice(0, 4).join("\n"));
    process.exit(1);
  }
  set(d.file, src.replace(d.avant, d.apres));
  console.log(`ok [${d.name}] ${d.file}`);
}

// Phase 3: écrire
for (const [f, s] of contents) {
  writeFileSync(f, s);
  console.log(`écrit ${f} (${s.length} octets)`);
}
console.log("PATCH 7 APPLIQUÉ — " + diffs.length + " diffs.");
